function validate([features, responses]) {
  if (!Array.isArray(features) || features.length < 1 || features.length > 10000) return 'features needs 1 to 10^4 words.';
  if (features.some(f => typeof f !== 'string' || !/^[a-z]{1,10}$/.test(f))) return 'Each feature is 1 to 10 lowercase letters.';
  if (new Set(features).size !== features.length) return 'features must not repeat a word.';
  if (!Array.isArray(responses) || responses.length < 1 || responses.length > 100) return 'responses needs 1 to 100 strings.';
  if (responses.some(r => typeof r !== 'string' || r.length > 1000 || !/^[a-z]+( [a-z]+)*$/.test(r))) return 'Each response is up to 1000 characters of lowercase words separated by single spaces.';
  return null;
}

