function sortFeatures(features, responses) {
  const popularity = new Map();
  for (const feature of features) {
    popularity.set(feature, 0);
  }

  for (const response of responses) {
    const words = new Set(response.split(' '));
    for (const word of words) {
      if (popularity.has(word)) {
        popularity.set(word, popularity.get(word) + 1);
      }
    }
  }

  const order = features.map((feature, index) => index);
  order.sort((a, b) => popularity.get(features[b]) - popularity.get(features[a]) || a - b);
  return order.map(index => features[index]);
}

