function sortFeatures(features, responses) {
  const counts = features.map(feature => responses.filter(response => response.split(' ').includes(feature)).length);
  const used = features.map(() => false);
  const result = [];
  for (let round = 0; round < features.length; round++) {
    let pick = -1;
    for (let i = 0; i < features.length; i++) {
      if (!used[i] && (pick === -1 || counts[i] > counts[pick])) pick = i;
    }
    used[pick] = true;
    result.push(features[pick]);
  }
  return result;
}

