function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const letters = large ? 'abcdefghij' : 'abc';
  const word = (lo, hi) => { let w = ''; const len = int(lo, hi); for (let i = 0; i < len; i++) w += letters[int(0, letters.length - 1)]; return w; };
  const featureCount = large ? 2000 : int(1, 6);
  const seen = new Set();
  const features = [];
  while (features.length < featureCount) {
    const w = large ? word(2, 6) : word(1, 3);
    if (!seen.has(w)) { seen.add(w); features.push(w); }
  }
  const responseCount = large ? 100 : int(1, 6);
  const responses = [];
  for (let r = 0; r < responseCount; r++) {
    const words = [];
    let length = -1;
    const target = large ? int(600, 1000) : int(1, 20);
    while (true) {
      let w;
      const roll = rand();
      if (roll < 0.6) w = features[int(0, features.length - 1)];
      else if (roll < 0.8) w = features[int(0, features.length - 1)] + letters[int(0, letters.length - 1)];
      else w = large ? word(1, 10) : word(1, 3);
      if (w.length > 10) w = w.slice(0, 10);
      if (length + 1 + w.length > target && words.length > 0) break;
      if (length + 1 + w.length > 1000) break;
      words.push(w);
      length += 1 + w.length;
    }
    responses.push(words.join(' '));
  }
  return [features, responses];
}
